tool.schemaJson:
{
  "type": "object",
  "properties": {
    "datasetSid": {
      "type": "string",
      "description": "The dataset ID (sid) to query. Obtain from datav-list-datasets."
    },
    "params": {
      "type": "object",
      "description": "Query parameters as a JSON object. Each key must match a ${paramName} placeholder in the dataset SQL. Values are bound as parameterized SQL variables (NOT string concatenation), preventing SQL injection.",
      "additionalProperties": true
    },
    "maxRows": {
      "type": "integer",
      "minimum": 1,
      "maximum": 1000,
      "description": "Maximum number of rows to return. Server-side hard clamp applies: null or non-positive values fall back to the platform config (nop.datav.chatbi.max-rows, default 1000); values above the config are clamped down to it. The maximum here is a default snapshot hint for the LLM only — the runtime config is authoritative."
    }
  },
  "required": ["datasetSid"]
}
